#!/usr/bin/env bash
# Static CI gate for calamares-settings-ubuntu (KzhenTo fork).
# Requires: dpkg-dev, gettext, desktop-file-utils, file, python3 + python3-yaml.
# Exits non-zero when any check fails; all checks always run to report everything.

set -uo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

FAILURES=0
HAVE_YAML=0

section() { printf '\n== %s ==\n' "$*"; }
ok()      { printf '  OK   %s\n' "$*"; }
bad()     { printf '  FAIL %s\n' "$*" >&2; FAILURES=$((FAILURES + 1)); }
need()    { command -v "$1" >/dev/null 2>&1 || bad "missing tool: $1"; }

# ---------------------------------------------------------------- Toolchain
section "Toolchain"
for tool in dpkg-parsechangelog msgfmt desktop-file-validate file python3 git; do
    need "$tool"
done
if python3 -c 'import yaml' >/dev/null 2>&1; then
    HAVE_YAML=1
else
    bad "missing Python module PyYAML (python3-yaml)"
fi

# ---------------------------------------------------------------- Debian metadata
section "Debian metadata"
SRC=""
VER=""
if SRC=$(dpkg-parsechangelog -S Source 2>/dev/null) \
    && VER=$(dpkg-parsechangelog -S Version 2>/dev/null) \
    && DIST=$(dpkg-parsechangelog -S Distribution 2>/dev/null); then
    ok "changelog: ${SRC} ${VER} (${DIST})"
else
    bad "cannot parse debian/changelog header"
fi

CTRL_SRC=$(awk '$1 == "Source:" { print $2; exit }' debian/control 2>/dev/null || true)
if [[ -n "$CTRL_SRC" && "$CTRL_SRC" == "$SRC" ]]; then
    ok "debian/control Source matches changelog"
else
    bad "Source mismatch: control='${CTRL_SRC}' changelog='${SRC}'"
fi

mapfile -t PKGS < <(awk '$1 == "Package:" { print $2 }' debian/control 2>/dev/null | sort)
DUPES=$(printf '%s\n' "${PKGS[@]}" | uniq -d)
if [[ -z "$DUPES" && "${#PKGS[@]}" -ge 4 ]]; then
    ok "binary packages: ${PKGS[*]}"
else
    bad "binary package list duplicated or too short: ${PKGS[*]} / duplicates: ${DUPES}"
fi
grep -q '^Rules-Requires-Root: no$' debian/control \
    && ok "Rules-Requires-Root: no" \
    || bad "debian/control missing Rules-Requires-Root: no"

# calamares-settings-ubuntu-common-data conflicts with common versions below
# 1:25.04.16. The source version must stay above that threshold, otherwise the
# two freshly built packages conflict with each other during installation.
if command -v dpkg >/dev/null 2>&1 && [[ -n "$VER" ]]; then
    if dpkg --compare-versions "$VER" ge '1:25.04.16'; then
        ok "version $VER is above the common-data conflict threshold"
    else
        bad "version $VER is below 1:25.04.16; common-data will conflict with common"
    fi
fi

# ---------------------------------------------------------------- Source layout
section "Source layout"
REQUIRED_DIRS=(
    common/modules common/modules/automirror common/modules/pkgselect
    common/basicwallpaper common/snap-seed-glue-emb
    kzhento kzhento/po kzhento/modules kzhento/oem kzhento/branding
    lubuntu lubuntu/po lubuntu/modules lubuntu/oem lubuntu/branding
    ubuntuunity ubuntuunity/po ubuntuunity/modules ubuntuunity/oem ubuntuunity/branding
)
for path in "${REQUIRED_DIRS[@]}"; do
    [[ -d "$path" ]] || bad "missing directory: $path"
done

REQUIRED_FILES=(
    Makefile README.md debian/rules debian/control debian/changelog
    common/fixconkeys-part1 common/fixconkeys-part2
    common/basicwallpaper/CMakeLists.txt
    common/snap-seed-glue-emb/main.go
    common/modules/automirror/main.py
)
for flavor in kzhento lubuntu ubuntuunity; do
    REQUIRED_FILES+=(
        "$flavor/calamares-launch-normal"
        "$flavor/calamares-logs-helper"
        "$flavor/settings.conf"
        "$flavor/po/POTFILES.in"
        "$flavor/oem/sudoers.oem"
        "$flavor/oem/calamares-oemprep.sh"
    )
done
for path in "${REQUIRED_FILES[@]}"; do
    [[ -f "$path" ]] || bad "missing file: $path"
done
ok "checked ${#REQUIRED_DIRS[@]} directories and ${#REQUIRED_FILES[@]} files"

# ---------------------------------------------------------------- Install manifests
section "deb install manifests"
MANIFEST_COUNT=0
for manifest in debian/*.install; do
    [[ -f "$manifest" ]] || continue
    MANIFEST_COUNT=$((MANIFEST_COUNT + 1))
    while read -r source_path dest _rest; do
        [[ -z "$source_path" || "$source_path" == \#* ]] && continue
        if [[ -z "$dest" || ( "$dest" != usr/* && "$dest" != etc/* ) ]]; then
            bad "$manifest: invalid destination '$dest' (source: $source_path)"
            continue
        fi
        if [[ -e "$source_path" ]]; then
            continue
        fi
        # .desktop files and oemconfig.tar.gz are generated by make at build time.
        if [[ "$source_path" == *.desktop ]]; then
            if [[ -f "${source_path}.in" ]]; then
                continue
            fi
            bad "$manifest: missing desktop source ${source_path}.in"
            continue
        fi
        if [[ "$source_path" == *.tar.gz && "$source_path" == *oemconfig.tar.gz ]]; then
            flavor=${source_path%%/*}
            [[ -d "$flavor/oem" ]] || bad "$manifest: missing OEM source directory $flavor/oem"
            continue
        fi
        bad "$manifest: source path does not exist: $source_path"
    done < "$manifest"
done
ok "checked $MANIFEST_COUNT .install manifests"

# ---------------------------------------------------------------- Desktop entries
section "Desktop entries and translation lists"
DESKTOPS=(
    kzhento/kubuntu-calamares.desktop.in
    lubuntu/lubuntu-calamares.desktop.in
    ubuntuunity/ubuntu-unity-calamares.desktop.in
)
for entry in "${DESKTOPS[@]}"; do
    [[ -f "$entry" ]] || { bad "missing desktop entry: $entry"; continue; }
    for key in '[Desktop Entry]' 'Name=' 'Exec=' 'Type=Application'; do
        grep -qF "$key" "$entry" || bad "$entry: missing $key"
    done
    po_dir="$(dirname "$entry")/po"
    base="$(basename "$entry")"
    grep -qxF "$base" "$po_dir/POTFILES.in" 2>/dev/null \
        || bad "$po_dir/POTFILES.in does not list $base"
done
ok "checked ${#DESKTOPS[@]} desktop entries"

# ---------------------------------------------------------------- Syntax checks
section "Configuration syntax (YAML)"
if (( HAVE_YAML )); then
    mapfile -t YAML_FILES < <(find common kzhento lubuntu ubuntuunity -type f \
        \( -name '*.conf' -o -name '*.conf.oem' -o -name '*.desc' \) -print | sort)
    if python3 - "${YAML_FILES[@]}" <<'PY'
import sys
import yaml

failed = False
for name in sys.argv[1:]:
    with open(name, encoding="utf-8") as handle:
        text = handle.read()
    significant = "\n".join(
        line for line in text.splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    )
    if significant.startswith("["):
        continue  # INI-style .conf (sddm.conf, lightdm.conf, ...)
    try:
        # Calamares upstream ships a literal tab in welcome.conf; YAML itself is fine.
        yaml.safe_load(text.replace("\t", "    "))
    except Exception as exc:  # noqa: BLE001 - gate reports every broken file
        print(f"  FAIL YAML {name}: {exc}", file=sys.stderr)
        failed = True
sys.exit(1 if failed else 0)
PY
    then
        ok "parsed ${#YAML_FILES[@]} YAML configs"
    else
        FAILURES=$((FAILURES + 1))
    fi
fi

section "Script syntax"
mapfile -t PY_FILES < <(find common kzhento lubuntu ubuntuunity -type f -name '*.py' -print | sort)
if (( ${#PY_FILES[@]} )); then
    if python3 - "${PY_FILES[@]}" <<'PY'
import ast
import sys

failed = False
for name in sys.argv[1:]:
    try:
        with open(name, encoding="utf-8") as handle:
            ast.parse(handle.read(), filename=name)
    except Exception as exc:  # noqa: BLE001
        print(f"  FAIL Python {name}: {exc}", file=sys.stderr)
        failed = True
sys.exit(1 if failed else 0)
PY
    then
        ok "parsed ${#PY_FILES[@]} Python scripts"
    else
        FAILURES=$((FAILURES + 1))
    fi
fi

SHELL_FILES=()
while IFS= read -r -d '' file; do
    if head -c 80 "$file" | grep -qE '^#!.*(ba|da|z|k)?sh'; then
        SHELL_FILES+=("$file")
    fi
done < <(git ls-files -z)
for file in "${SHELL_FILES[@]}"; do
    bash -n "$file" || bad "shell syntax error: $file"
done
ok "checked ${#SHELL_FILES[@]} shell scripts"

section "Translation files"
mapfile -t PO_FILES < <(find kzhento/po lubuntu/po ubuntuunity/po -type f -name '*.po' -print | sort)
PO_BAD=0
for file in "${PO_FILES[@]}"; do
    msgfmt -c -o /dev/null "$file" 2>/dev/null || { bad "invalid PO file: $file"; PO_BAD=$((PO_BAD + 1)); }
done
(( PO_BAD == 0 )) && ok "validated ${#PO_FILES[@]} .po files"

section "Branding assets"
mapfile -t IMAGE_FILES < <(find kzhento/branding lubuntu/branding ubuntuunity/branding -type f \
    \( -iname '*.png' -o -iname '*.svg' -o -iname '*.jpg' \) -print | sort)
IMAGE_BAD=0
for file in "${IMAGE_FILES[@]}"; do
    [[ -s "$file" ]] || { bad "empty image: $file"; IMAGE_BAD=$((IMAGE_BAD + 1)); continue; }
    mime=$(file --mime-type -b "$file")
    [[ "$mime" == image/* ]] || { bad "$file is not an image (MIME=$mime)"; IMAGE_BAD=$((IMAGE_BAD + 1)); }
done
(( IMAGE_BAD == 0 )) && ok "validated ${#IMAGE_FILES[@]} branding images"
for brand_dir in kzhento/branding/* lubuntu/branding/* ubuntuunity/branding/*; do
    [[ -d "$brand_dir" ]] || continue
    for asset in branding.desc show.qml logo.png icon.png welcome.png; do
        [[ -f "$brand_dir/$asset" ]] || bad "$brand_dir missing $asset"
    done
done

# ---------------------------------------------------------------- Repository hygiene
section "Repository hygiene"
if git grep -nE '^(<<<<<<< |>>>>>>> )' -- . >/dev/null 2>&1; then
    git grep -nE '^(<<<<<<< |>>>>>>> )' -- . >&2 || true
    bad "unresolved conflict markers found"
else
    ok "no conflict markers"
fi

printf '\n'
if (( FAILURES > 0 )); then
    printf 'CI gate failed: %d issue(s)\n' "$FAILURES" >&2
    exit 1
fi
printf 'CI gate passed\n'
